using JamunaBank.Procurement.API.Constants;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Services.Interfaces;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JamunaBank.Procurement.API.Controllers;
[ApiController,Authorize]
public sealed class SupportingController(ISupportingService service):ControllerBase
{
 [HttpPost("api/attachments")]public async Task<ActionResult<ApiResponse<StoredProcedureResult>>>AddAttachment(AddAttachmentMetadataRequest r,CancellationToken c)=>Map(await service.AddAttachmentAsync(r,c),"Attachment metadata added.");[HttpGet("api/attachments")]public async Task<ActionResult<ApiResponse<IReadOnlyList<AttachmentMetadataDto>>>>Attachments([FromQuery]string entityType,[FromQuery]long entityId,CancellationToken c){var x=await service.GetAttachmentsAsync(entityType,entityId,c);return Ok(ApiResponse<IReadOnlyList<AttachmentMetadataDto>>.Ok(x,"Attachments loaded.",HttpContext.TraceIdentifier));}[HttpPost("api/comments")]public async Task<ActionResult<ApiResponse<StoredProcedureResult>>>AddComment(AddCommentRequest r,CancellationToken c)=>Map(await service.AddCommentAsync(r,c),"Comment added.");[HttpGet("api/comments")]public async Task<ActionResult<ApiResponse<IReadOnlyList<CommentDto>>>>Comments([FromQuery]long requisitionId,CancellationToken c){var x=await service.GetCommentsAsync(requisitionId,c);return Ok(ApiResponse<IReadOnlyList<CommentDto>>.Ok(x,"Comments loaded.",HttpContext.TraceIdentifier));}[HttpGet("api/requisitions/{id:long}/approval-history")]public async Task<ActionResult<ApiResponse<IReadOnlyList<ApprovalHistoryDto>>>>Approval(long id,CancellationToken c){var x=await service.GetApprovalHistoryAsync(id,c);return Ok(ApiResponse<IReadOnlyList<ApprovalHistoryDto>>.Ok(x,"Approval history loaded.",HttpContext.TraceIdentifier));}[HttpGet("api/requisitions/{id:long}/workflow-history")]public async Task<ActionResult<ApiResponse<IReadOnlyList<WorkflowHistoryDto>>>>Workflow(long id,CancellationToken c){var x=await service.GetWorkflowHistoryAsync(id,c);return Ok(ApiResponse<IReadOnlyList<WorkflowHistoryDto>>.Ok(x,"Workflow history loaded.",HttpContext.TraceIdentifier));}[HttpGet("api/requisitions/{id:long}/procurement-status-history")]public async Task<ActionResult<ApiResponse<IReadOnlyList<SupportingProcurementStatusHistoryDto>>>>Procurement(long id,CancellationToken c){var x=await service.GetProcurementHistoryAsync(id,c);return Ok(ApiResponse<IReadOnlyList<SupportingProcurementStatusHistoryDto>>.Ok(x,"Procurement status history loaded.",HttpContext.TraceIdentifier));}
 private ActionResult<ApiResponse<StoredProcedureResult>>Map(StoredProcedureResult?r,string m)=>r is not null&&r.ResultCode==ResultCodes.Success?Ok(ApiResponse<StoredProcedureResult>.Ok(r,m,HttpContext.TraceIdentifier)):BadRequest(ApiResponse<StoredProcedureResult>.Fail("Operation failed.",[r?.ResultMessage??"No stored-procedure result was returned."],HttpContext.TraceIdentifier));
}
